using System;using System.Data.SqlClient;using System.Web.UI;
namespace Training.Manager{public partial class AttendanceReport:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string MID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(MID))Response.Redirect("~/Default.aspx");if(!IsPostBack){if(Session["SessionID"]!=null&&string.IsNullOrWhiteSpace(txtSessionID.Text))txtSessionID.Text=Session["SessionID"].ToString();BindGrid();}}
private void BindGrid(){string q="SELECT SA.AttendanceID,SA.TrainingID,SA.SessionID,SA.EmpID,EBM.EmpName,ISNULL(SA.AttendanceStatus,'Pending') AttendanceStatus,SA.Remarks,SA.CreatedOn FROM SessionAttendance SA INNER JOIN EmpBasicMaster EBM ON SA.EmpID=EBM.EmpID INNER JOIN TrainingDetails TD ON SA.TrainingID=TD.TrainingID INNER JOIN TrainingLocationMaster L ON TD.TrainingLocation=L.TrainingLocation INNER JOIN ManagerMaster M ON M.TrainingLocationID=L.TrainingLocationID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y'";var p=new System.Collections.Generic.List<SqlParameter>();p.Add(new SqlParameter("@ManagerID",MID));if(!string.IsNullOrWhiteSpace(txtTrainingID.Text)){q+=" AND SA.TrainingID=@TrainingID";p.Add(new SqlParameter("@TrainingID",txtTrainingID.Text.Trim()));}if(!string.IsNullOrWhiteSpace(txtSessionID.Text)){q+=" AND SA.SessionID=@SessionID";p.Add(new SqlParameter("@SessionID",txtSessionID.Text.Trim()));}if(!string.IsNullOrWhiteSpace(txtSearch.Text)){q+=" AND (SA.EmpID LIKE @Search OR EBM.EmpName LIKE @Search)";p.Add(new SqlParameter("@Search","%"+txtSearch.Text.Trim()+"%"));}q+=" ORDER BY SA.CreatedOn DESC";gvReport.DataSource=obj.GetDataTable(q,p.ToArray());gvReport.DataBind();}protected void btnSearch_Click(object s,EventArgs e){BindGrid();}}}